public void loadDefaultModels(Path modelFile) {
    try (InputStream in = Files.newInputStream(modelFile)) {
        loadDefaultModels(in);
    } catch (IOException e) {
        throw new RuntimeException("Unable to read the default media type registry", e);
    }
}
